    // ------------------------------------------------------------------ audio

    fun sfxAsset(id: String): MediaAsset {
        val e = Synth.sfxList.first { it.id == id }
        val f = File(dir, "sfx_$id.wav")
        if (!f.exists()) { val a = Synth.sfx(id); WavWriter.write(f, a.samples, a.sampleRate, a.channels) }
        val a = Synth.sfx(id)
        return MediaAsset("res_sfx_$id", Uri.fromFile(f).toString(), e.name, MediaType.AUDIO, "audio/wav", a.durationUs, hasAudio = true, hasVideo = false, sampleRate = a.sampleRate, channelCount = 1, folder = "Bruitages", tags = listOf("cuttinx", e.category))
    }

    fun musicAsset(id: String): MediaAsset {
        val e = Synth.musicList.first { it.id == id }
        val f = File(dir, "music_$id.wav")
        if (!f.exists()) { val a = Synth.music(id); val tmp = File(dir, "music_$id.tmp"); WavWriter.write(tmp, a.samples, a.sampleRate, a.channels); tmp.renameTo(f) }
        return MediaAsset("res_music_$id", Uri.fromFile(f).toString(), e.name, MediaType.AUDIO, "audio/wav", e.seconds * 1_000_000L, hasAudio = true, hasVideo = false, sampleRate = Synth.SR, channelCount = 2, folder = "Musiques", tags = listOf("cuttinx", e.mood, "${e.bpm} BPM"))
    }

    fun isGenerated(kind: String, id: String) = File(dir, "${kind}_$id.wav").exists()

    // ------------------------------------------------------------------ graphics

    fun stickerAsset(id: String): MediaAsset {
        val e = stickers.first { it.id == id }
        val f = File(dir, "st_$id.png")
        if (!f.exists()) save(f, drawSticker(id, 512))
        return MediaAsset("res_st_$id", Uri.fromFile(f).toString(), e.name, MediaType.IMAGE, "image/png", 0, 512, 512, folder = "Autocollants", tags = listOf("cuttinx", e.category))
    }

    fun backgroundAsset(id: String, w: Int = 1080, h: Int = 1920): MediaAsset {
        val e = backgrounds.first { it.id == id }
        val f = File(dir, "${id}_${w}x$h.png")
        if (!f.exists()) save(f, drawBackground(id, w, h))
        return MediaAsset("res_${id}_${w}x$h", Uri.fromFile(f).toString(), e.name, MediaType.IMAGE, "image/png", 0, w, h, folder = "Fonds", tags = listOf("cuttinx", e.category))
    }

    private fun save(f: File, b: Bitmap) { val tmp = File(f.path + ".tmp"); tmp.outputStream().use { b.compress(Bitmap.CompressFormat.PNG, 100, it) }; tmp.renameTo(f) }

    fun drawSticker(id: String, s: Int): Bitmap {
        val b = Bitmap.createBitmap(s, s, Bitmap.Config.ARGB_8888)
        val c = Canvas(b)
        val yellow = 0xFFFFCC1F.toInt(); val white = Color.WHITE; val black = 0xFF111111.toInt()
        val fill = Paint(Paint.ANTI_ALIAS_FLAG).apply { color = yellow }
        val stroke = Paint(Paint.ANTI_ALIAS_FLAG).apply { style = Paint.Style.STROKE; strokeWidth = s * 0.035f; color = black; strokeJoin = Paint.Join.ROUND; strokeCap = Paint.Cap.ROUND }
        val m = s * 0.1f; val cx = s / 2f; val cy = s / 2f; val r = s / 2f - m
        fun star(points: Int, inner: Float): Path { val p = Path(); for (i in 0 until points * 2) { val a = -PI / 2 + i * PI / points; val rr = if (i % 2 == 0) r else r * inner; val x = cx + (rr * cos(a)).toFloat(); val y = cy + (rr * sin(a)).toFloat(); if (i == 0) p.moveTo(x, y) else p.lineTo(x, y) }; p.close(); return p }
        fun face(mouth: Path.() -> Unit, eyes: Boolean = true, color: Int = yellow) {
            fill.color = color; c.drawCircle(cx, cy, r, fill); c.drawCircle(cx, cy, r, stroke)
            val ep = Paint(Paint.ANTI_ALIAS_FLAG).apply { this.color = black }
            if (eyes) { c.drawCircle(cx - r * 0.35f, cy - r * 0.2f, r * 0.1f, ep); c.drawCircle(cx + r * 0.35f, cy - r * 0.2f, r * 0.1f, ep) }
            val mp = Path().apply(mouth); c.drawPath(mp, stroke)
        }
        when (id) {
            "star" -> { val p = star(5, 0.45f); c.drawPath(p, fill); c.drawPath(p, stroke) }
            "sparkle" -> { fill.color = white; val p = star(4, 0.2f); c.drawPath(p, fill) }
            "burst" -> { fill.color = 0xFFFF3D3D.toInt(); val p = star(12, 0.7f); c.drawPath(p, fill); c.drawPath(p, stroke) }
            "heart" -> { fill.color = 0xFFFF3D6E.toInt(); val p = Path().apply { moveTo(cx, s * 0.82f); cubicTo(s * 0.05f, s * 0.5f, s * 0.2f, s * 0.12f, cx, s * 0.3f); cubicTo(s * 0.8f, s * 0.12f, s * 0.95f, s * 0.5f, cx, s * 0.82f); close() }; c.drawPath(p, fill); c.drawPath(p, stroke) }
            "circle" -> { c.drawCircle(cx, cy, r, fill) }
            "ring" -> { stroke.color = yellow; stroke.strokeWidth = s * 0.07f; c.drawCircle(cx, cy, r, stroke) }
            "square" -> { c.drawRoundRect(RectF(m, m, s - m, s - m), s * 0.12f, s * 0.12f, fill) }
            "triangle" -> { val p = Path().apply { moveTo(cx, m); lineTo(s - m, s - m); lineTo(m, s - m); close() }; c.drawPath(p, fill); c.drawPath(p, stroke) }
            "arrow" -> { fill.color = 0xFFFF3D3D.toInt(); val p = Path().apply { moveTo(m, cy - s * 0.08f); lineTo(s * 0.6f, cy - s * 0.08f); lineTo(s * 0.6f, cy - s * 0.22f); lineTo(s - m, cy); lineTo(s * 0.6f, cy + s * 0.22f); lineTo(s * 0.6f, cy + s * 0.08f); lineTo(m, cy + s * 0.08f); close() }; c.drawPath(p, fill); c.drawPath(p, stroke) }
            "arrow_curved" -> { stroke.color = 0xFFFF3D3D.toInt(); stroke.strokeWidth = s * 0.06f; val p = Path().apply { moveTo(m, s - m * 2); quadTo(m, m, s - m * 2.5f, m * 2) }; c.drawPath(p, stroke); val h = Path().apply { moveTo(s - m * 3.6f, m * 1.0f); lineTo(s - m * 1.6f, m * 2.1f); lineTo(s - m * 3.2f, m * 3.6f) }; c.drawPath(h, stroke) }
            "highlight" -> { fill.color = 0x99FFCC1F.toInt(); c.drawRoundRect(RectF(m * 0.5f, cy - s * 0.12f, s - m * 0.5f, cy + s * 0.12f), s * 0.04f, s * 0.04f, fill) }
            "bubble" -> { fill.color = white; val p = Path().apply { addRoundRect(RectF(m, m, s - m, s * 0.72f), s * 0.12f, s * 0.12f, Path.Direction.CW); moveTo(s * 0.3f, s * 0.7f); lineTo(s * 0.22f, s - m); lineTo(s * 0.48f, s * 0.7f) }; c.drawPath(p, fill); c.drawPath(p, stroke) }
            "check" -> { fill.color = 0xFF2ECC71.toInt(); c.drawCircle(cx, cy, r, fill); stroke.color = white; stroke.strokeWidth = s * 0.08f; c.drawPath(Path().apply { moveTo(s * 0.3f, cy); lineTo(s * 0.45f, s * 0.66f); lineTo(s * 0.72f, s * 0.34f) }, stroke) }
            "cross" -> { fill.color = 0xFFE74C3C.toInt(); c.drawCircle(cx, cy, r, fill); stroke.color = white; stroke.strokeWidth = s * 0.08f; c.drawLine(s * 0.33f, s * 0.33f, s * 0.67f, s * 0.67f, stroke); c.drawLine(s * 0.67f, s * 0.33f, s * 0.33f, s * 0.67f, stroke) }
            "smile" -> face({ addArc(RectF(cx - r * 0.5f, cy - r * 0.2f, cx + r * 0.5f, cy + r * 0.55f), 20f, 140f) })
            "laugh" -> face({ moveTo(cx - r * 0.5f, cy + r * 0.1f); quadTo(cx, cy + r * 0.8f, cx + r * 0.5f, cy + r * 0.1f); close() })
            "wow" -> face({ addOval(RectF(cx - r * 0.15f, cy + r * 0.15f, cx + r * 0.15f, cy + r * 0.55f), Path.Direction.CW) })
            "love" -> { face({ addArc(RectF(cx - r * 0.45f, cy - r * 0.1f, cx + r * 0.45f, cy + r * 0.5f), 20f, 140f) }, eyes = false); fill.color = 0xFFFF3D6E.toInt(); for (sx in listOf(-1, 1)) { val ex = cx + sx * r * 0.35f; val ey = cy - r * 0.25f; val k = r * 0.16f; c.drawPath(Path().apply { moveTo(ex, ey + k); cubicTo(ex - k * 2, ey, ex - k, ey - k * 1.4f, ex, ey - k * 0.4f); cubicTo(ex + k, ey - k * 1.4f, ex + k * 2, ey, ex, ey + k) }, fill) } }
            "fire" -> { fill.shader = LinearGradient(0f, s.toFloat(), 0f, 0f, 0xFFFF3D00.toInt(), 0xFFFFCC1F.toInt(), Shader.TileMode.CLAMP); val p = Path().apply { moveTo(cx, m); cubicTo(s * 0.95f, s * 0.45f, s * 0.8f, s - m, cx, s - m); cubicTo(s * 0.2f, s - m, s * 0.05f, s * 0.5f, s * 0.35f, s * 0.3f); cubicTo(s * 0.35f, s * 0.5f, s * 0.45f, s * 0.55f, cx, s * 0.6f); cubicTo(s * 0.5f, s * 0.4f, s * 0.42f, s * 0.25f, cx, m); close() }; c.drawPath(p, fill) }
            "lowerthird" -> { fill.color = yellow; c.drawRect(0f, s * 0.55f, s * 0.95f, s * 0.75f, fill); fill.color = white; c.drawRect(0f, s * 0.75f, s * 0.7f, s * 0.84f, fill) }
            "bell" -> { fill.color = yellow; val p = Path().apply { moveTo(cx, m); cubicTo(s * 0.8f, m, s * 0.75f, s * 0.6f, s * 0.88f, s * 0.75f); lineTo(s * 0.12f, s * 0.75f); cubicTo(s * 0.25f, s * 0.6f, s * 0.2f, m, cx, m); close() }; c.drawPath(p, fill); c.drawPath(p, stroke); c.drawCircle(cx, s * 0.84f, s * 0.07f, fill); c.drawCircle(cx, s * 0.84f, s * 0.07f, stroke) }
            "like" -> { fill.color = 0xFF29A3FF.toInt(); c.drawCircle(cx, cy, r, fill); fill.color = white; c.drawRoundRect(RectF(s * 0.28f, s * 0.45f, s * 0.38f, s * 0.72f), 8f, 8f, fill); c.drawPath(Path().apply { moveTo(s * 0.42f, s * 0.72f); lineTo(s * 0.68f, s * 0.72f); quadTo(s * 0.74f, s * 0.6f, s * 0.72f, s * 0.48f); lineTo(s * 0.55f, s * 0.48f); lineTo(s * 0.57f, s * 0.3f); quadTo(s * 0.5f, s * 0.26f, s * 0.47f, s * 0.32f); lineTo(s * 0.42f, s * 0.47f); close() }, fill) }
            "frame" -> { stroke.color = white; stroke.strokeWidth = s * 0.04f; c.drawRect(m, m, s - m, s - m, stroke); stroke.color = yellow; val k = s * 0.15f; for ((x, y) in listOf(m to m, s - m to m, m to s - m, s - m to s - m)) { val dx = if (x < cx) k else -k; val dy = if (y < cy) k else -k; c.drawLine(x, y, x + dx, y, stroke); c.drawLine(x, y, x, y + dy, stroke) } }
            "rec" -> { fill.color = 0xFFFF2D2D.toInt(); c.drawCircle(s * 0.25f, cy, s * 0.1f, fill); val tp = Paint(Paint.ANTI_ALIAS_FLAG).apply { color = white; textSize = s * 0.22f; typeface = Typeface.DEFAULT_BOLD }; c.drawText("REC", s * 0.4f, cy + s * 0.08f, tp) }
        }
        return b
    }

    fun drawBackground(id: String, w: Int, h: Int): Bitmap {
        val b = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888)
        val c = Canvas(b)
        val p = Paint(Paint.ANTI_ALIAS_FLAG)
        fun grad(a: Long, bb: Long, angle: Boolean = true) { p.shader = LinearGradient(0f, 0f, if (angle) w.toFloat() else 0f, h.toFloat(), a.toInt(), bb.toInt(), Shader.TileMode.CLAMP); c.drawRect(0f, 0f, w.toFloat(), h.toFloat(), p); p.shader = null }
        when (id) {
            "bg_sunset" -> grad(0xFFFF7E5F, 0xFF6A3093)
            "bg_ocean" -> grad(0xFF2193B0, 0xFF0B1F3A)
            "bg_essence" -> grad(0xFF0A0A0B, 0xFF3A2E00, false)
            "bg_mint" -> grad(0xFFB8F5D0, 0xFF3AB795)
            "bg_night" -> grad(0xFF141E30, 0xFF243B55, false)
            "bg_peach" -> grad(0xFFFFE0C7, 0xFFFF9A8B)
            "bg_radial" -> { c.drawColor(0xFF070707.toInt()); p.shader = RadialGradient(w / 2f, h * 0.35f, maxOf(w, h) * 0.6f, 0xFFFFF2B0.toInt(), 0x00000000, Shader.TileMode.CLAMP); c.drawRect(0f, 0f, w.toFloat(), h.toFloat(), p) }
            "bg_grid" -> { c.drawColor(0xFF101014.toInt()); p.color = 0x33FFFFFF; p.strokeWidth = 2f; val st = w / 12f; var x = 0f; while (x < w) { c.drawLine(x, 0f, x, h.toFloat(), p); x += st }; var y = 0f; while (y < h) { c.drawLine(0f, y, w.toFloat(), y, p); y += st } }
            "bg_dots" -> { c.drawColor(0xFFFFCC1F.toInt()); p.color = 0x33000000; val st = w / 14f; var y = st / 2; var row = 0; while (y < h) { var x = if (row % 2 == 0) st / 2 else st; while (x < w) { c.drawCircle(x, y, st * 0.18f, p); x += st }; y += st; row++ } }
            "bg_stripes" -> { c.drawColor(0xFF1B1B1F.toInt()); p.color = 0xFF2A2A30.toInt(); p.strokeWidth = w / 16f; var x = -h.toFloat(); while (x < w) { c.drawLine(x, h.toFloat(), x + h, 0f, p); x += w / 6f } }
            "bg_paper" -> { c.drawColor(0xFFF3EBDD.toInt()); val r = java.util.Random(3); for (i in 0 until w * h / 60) { p.color = if (r.nextBoolean()) 0x0D000000 else 0x10FFFFFF; c.drawPoint(r.nextInt(w).toFloat(), r.nextInt(h).toFloat(), p) } }
            "bg_bokeh" -> { grad(0xFF1A0B2E, 0xFF0B0B1A, false); val r = java.util.Random(11); for (i in 0 until 40) { val rad = w * (0.03f + r.nextFloat() * 0.09f); p.color = Color.argb(40 + r.nextInt(60), 255, 180 + r.nextInt(75), 60 + r.nextInt(150)); c.drawCircle(r.nextInt(w).toFloat(), r.nextInt(h).toFloat(), rad, p) } }
        }
        return b
    }
}
